package com.post200m;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(Post200mConfig.GROUP)
public interface Post200mConfig extends Config
{
	String GROUP = "post200mxp";

	@ConfigItem(
		keyName = "showSidePanel",
		name = "Show side panel",
		description = "Show the post-200M XP panel in the sidebar",
		position = 0
	)
	default boolean showSidePanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Also show post-200M XP as an on-screen overlay",
		position = 1
	)
	default boolean showOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "overlayDisplay",
		name = "Overlay shows",
		description = "What the on-screen overlay displays for each skill. XP gained is the resettable session counter; all-time totals stay in the side panel",
		position = 2
	)
	default OverlayDisplay overlayDisplay()
	{
		return OverlayDisplay.BOTH;
	}

	enum OverlayDisplay
	{
		XP_GAINED("XP gained"),
		XP_PER_HOUR("XP/hr"),
		BOTH("Both");

		private final String displayName;

		OverlayDisplay(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	@ConfigItem(
		keyName = "showSessionXp",
		name = "Show session XP",
		description = "Also show XP gained this session next to the totals",
		position = 3
	)
	default boolean showSessionXp()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showXpPerHour",
		name = "Show XP/hr",
		description = "Show the XP per hour rate for each skill",
		position = 4
	)
	default boolean showXpPerHour()
	{
		return true;
	}

	@Range(min = 1, max = 60)
	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "pauseRateAfter",
		name = "Pause rate after",
		description = "Stop counting time towards XP/hr after this long without gaining XP",
		position = 5
	)
	default int pauseRateAfter()
	{
		return 3;
	}
}

package com.post200m;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.QuantityFormatter;

class Post200mOverlay extends OverlayPanel
{
	private static final int PANEL_WIDTH = 160;
	private static final int ICON_WIDTH = 30;
	private static final Point ICON_TEXT_GAP = new Point(6, 0);
	private static final Color SEPARATOR_COLOR = new Color(255, 255, 255, 40);

	private final Post200mPlugin plugin;
	private final Post200mConfig config;
	private final SkillIconManager skillIconManager;
	private final Map<String, BufferedImage> iconCache = new HashMap<>();

	@Inject
	Post200mOverlay(Post200mPlugin plugin, Post200mConfig config, SkillIconManager skillIconManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;
		setPosition(OverlayPosition.TOP_LEFT);
		// Vertical breathing room between skill rows
		panelComponent.setGap(new Point(0, 6));
		// Padding inside the box: left, top, right, bottom. The extra bottom
		// keeps the last row's text off the panel edge.
		panelComponent.setBorder(new Rectangle(6, 5, 6, 9));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		final List<Skill> skills = plugin.getDisplaySkills();
		if (skills.isEmpty())
		{
			return null;
		}

		final Post200mConfig.OverlayDisplay display = config.overlayDisplay();
		final boolean showGained = display != Post200mConfig.OverlayDisplay.XP_PER_HOUR;
		final boolean showRates = display != Post200mConfig.OverlayDisplay.XP_GAINED;

		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));

		int rows = 0;
		for (Skill skill : skills)
		{
			if (!plugin.isSkillOnOverlay(skill))
			{
				continue;
			}

			final long session = plugin.getSessionXp().getOrDefault(skill, 0L);
			final long xpPerHour = showRates ? plugin.getXpPerHour(skill) : -1;

			// XP Tracker style: skill icon on the left, lines beside it
			final PanelComponent lines = new PanelComponent();
			lines.setBackgroundColor(null);
			lines.setBorder(new Rectangle());
			lines.setPreferredSize(new Dimension(PANEL_WIDTH - ICON_WIDTH - ICON_TEXT_GAP.x, 0));

			if (showGained)
			{
				lines.getChildren().add(LineComponent.builder()
					.left("XP Gained:")
					.right(QuantityFormatter.formatNumber(session))
					.build());
			}
			if (showRates)
			{
				// Always show a value, even 0, so rows don't look ragged when a
				// skill hasn't gained XP this session (getXpPerHour returns -1).
				lines.getChildren().add(LineComponent.builder()
					.left("XP/hr:")
					.right(QuantityFormatter.formatNumber(Math.max(0, xpPerHour)))
					.build());
			}

			if (lines.getChildren().isEmpty())
			{
				continue;
			}

			// A faint divider between skills; not before the first row.
			if (rows > 0)
			{
				panelComponent.getChildren().add(new SeparatorComponent(PANEL_WIDTH - 12, SEPARATOR_COLOR));
			}

			final boolean singleLine = lines.getChildren().size() == 1;
			panelComponent.getChildren().add(SplitComponent.builder()
				.first(new ImageComponent(centeredIcon(skill, singleLine)))
				.second(lines)
				.orientation(ComponentOrientation.HORIZONTAL)
				.gap(ICON_TEXT_GAP)
				.build());
			rows++;
		}

		if (rows == 0)
		{
			panelComponent.getChildren().clear();
			return null;
		}

		return super.render(graphics);
	}

	/**
	 * Skill icons vary in width, which would stagger the text columns beside
	 * them. Padding each into a fixed-width canvas centers the icon and keeps
	 * every row's labels and values aligned.
	 */
	private BufferedImage centeredIcon(Skill skill, boolean small)
	{
		return iconCache.computeIfAbsent(skill.name() + small, k ->
		{
			final BufferedImage icon = skillIconManager.getSkillImage(skill, small);
			final BufferedImage padded = new BufferedImage(ICON_WIDTH, icon.getHeight(), BufferedImage.TYPE_INT_ARGB);
			final Graphics2D g = padded.createGraphics();
			g.drawImage(icon, (ICON_WIDTH - icon.getWidth()) / 2, 0, null);
			g.dispose();
			return padded;
		});
	}
}

package com.post200m;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;

class Post200mPanel extends PluginPanel
{
	private static final Border ROW_BORDER = new EmptyBorder(6, 8, 6, 8);
	private static final Border DROP_BORDER = new CompoundBorder(
		BorderFactory.createMatteBorder(2, 0, 0, 0, ColorScheme.BRAND_ORANGE),
		new EmptyBorder(4, 8, 6, 8));

	private final Post200mPlugin plugin;
	private final Post200mConfig config;
	private final SkillIconManager skillIconManager;
	private final JPanel skillList = new JPanel(new GridLayout(0, 1, 0, 4));
	// Draggable rows in display order, for hit-testing a drop position
	private final List<JPanel> skillRows = new ArrayList<>();
	// Value labels updated in place each tick, so rows aren't rebuilt.
	// valueLabels hold the total (+session) on the right; rateLabels hold the
	// xp/hr line under the skill name on the left.
	private final Map<Skill, JLabel> valueLabels = new EnumMap<>(Skill.class);
	private final Map<Skill, JLabel> rateLabels = new EnumMap<>(Skill.class);
	private final List<Skill> displayedSkills = new ArrayList<>();
	private static final Color RATE_COLOR = new Color(0x77, 0xc9, 0xa0);

	// Fixed header summary rows, toggled visible when they have a value
	private final JLabel totalGainedLabel = new JLabel("", SwingConstants.RIGHT);
	private final JLabel totalXpLabel = new JLabel("", SwingConstants.RIGHT);
	private JPanel totalGainedRow;
	private JPanel totalXpRow;

	private JPanel dropTarget;
	private boolean dragging;

	Post200mPanel(Post200mPlugin plugin, Post200mConfig config, SkillIconManager skillIconManager)
	{
		// Manage our own scrolling so the header (totals + buttons) stays pinned at the top.
		super(false);
		this.plugin = plugin;
		this.config = config;
		this.skillIconManager = skillIconManager;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout(0, 10));

		add(buildHeader(), BorderLayout.NORTH);

		skillList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		final JScrollPane scroll = new JScrollPane(skillList,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(new EmptyBorder(0, 0, 0, 0));
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		refresh();
	}

	private JPanel buildHeader()
	{
		final JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel title = new JLabel("Post-200M XP");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createVerticalStrut(8));

		final JButton resetSession = new JButton("Reset session");
		resetSession.setToolTipText("Reset the session XP shown on the overlay; all-time totals are never touched");
		resetSession.addActionListener(e -> plugin.resetSession());

		final JButton resetRate = new JButton("Reset XP/hr");
		resetRate.addActionListener(e -> plugin.resetXpPerHour());

		final JPanel resetRow = new JPanel(new GridLayout(1, 2, 6, 0));
		resetRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resetRow.add(resetSession);
		resetRow.add(resetRate);
		fullWidth(header, resetRow);
		header.add(Box.createVerticalStrut(4));

		final JButton clearOverlay = new JButton("Clear overlay");
		clearOverlay.setToolTipText("Untick every skill from the overlay");
		clearOverlay.addActionListener(e -> plugin.hideAllFromOverlay());
		fullWidth(header, clearOverlay);
		header.add(Box.createVerticalStrut(8));

		totalGainedLabel.setForeground(Color.WHITE);
		totalXpLabel.setForeground(Color.WHITE);
		totalGainedRow = buildSummaryRow("Total gained", totalGainedLabel, null);
		totalXpRow = buildSummaryRow("Total XP", totalXpLabel,
			"All XP on the account, including everything past 200M");
		totalGainedRow.setVisible(false);
		totalXpRow.setVisible(false);
		fullWidth(header, totalGainedRow);
		header.add(Box.createVerticalStrut(4));
		fullWidth(header, totalXpRow);

		return header;
	}

	/** Adds a component to a vertical box, left-aligned and stretched to full width. */
	private static void fullWidth(JPanel box, JComponent c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		box.add(c);
	}

	@Override
	public void onActivate()
	{
		refresh();
	}

	/**
	 * Per-tick update: rewrites the numbers on the existing rows, promoting
	 * to a full rebuild only when the set of skills changed.
	 */
	void update()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (!isShowing() || dragging)
			{
				return;
			}

			if (!plugin.getDisplaySkills().equals(displayedSkills))
			{
				refresh();
				return;
			}

			for (Skill skill : displayedSkills)
			{
				final long total = plugin.getTotalXp().getOrDefault(skill, 0L);
				final JLabel label = valueLabels.get(skill);
				if (label != null)
				{
					label.setText(gainedText(total, plugin.getSessionXp().get(skill)));
				}
				final JLabel rate = rateLabels.get(skill);
				if (rate != null)
				{
					rate.setText(rateText(plugin.getXpPerHour(skill)));
				}
			}
			updateTotals();
		});
	}

	void refresh()
	{
		if (dragging)
		{
			return;
		}

		skillList.removeAll();
		skillRows.clear();
		valueLabels.clear();
		rateLabels.clear();
		displayedSkills.clear();
		dropTarget = null;

		final List<Skill> skills = plugin.getDisplaySkills();
		displayedSkills.addAll(skills);
		if (skills.isEmpty())
		{
			final JLabel empty = new JLabel("<html>No post-200M XP tracked yet. Gain XP in a skill at 200M and it will show up here.</html>");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			skillList.add(empty);
		}
		else
		{
			for (Skill skill : skills)
			{
				final JPanel row = buildSkillRow(skill, plugin.getTotalXp().getOrDefault(skill, 0L));
				skillRows.add(row);
				skillList.add(row);
			}
		}

		updateTotals();

		skillList.revalidate();
		skillList.repaint();
	}

	/** Recomputes the header's Total gained / Total XP rows and their visibility. */
	private void updateTotals()
	{
		long grand = 0;
		for (Skill skill : displayedSkills)
		{
			grand += plugin.getTotalXp().getOrDefault(skill, 0L);
		}
		final boolean showGained = displayedSkills.size() > 1;
		totalGainedRow.setVisible(showGained);
		if (showGained)
		{
			totalGainedLabel.setText(QuantityFormatter.formatNumber(grand));
		}

		final long accountXp = plugin.getTotalAccountXp();
		final boolean showXp = accountXp > 0;
		totalXpRow.setVisible(showXp);
		if (showXp)
		{
			totalXpLabel.setText(QuantityFormatter.formatNumber(accountXp));
		}
	}

	private JPanel buildSkillRow(Skill skill, long total)
	{
		final JPanel row = baseRow();
		row.setToolTipText("Drag to reorder");
		row.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));

		final JCheckBox overlayToggle = new JCheckBox();
		overlayToggle.setSelected(plugin.isSkillOnOverlay(skill));
		overlayToggle.setToolTipText("Show " + skill.getName() + " on the overlay");
		overlayToggle.setOpaque(false);
		overlayToggle.setInheritsPopupMenu(true);
		overlayToggle.addActionListener(e -> plugin.setSkillOnOverlay(skill, overlayToggle.isSelected()));

		final JLabel nameLabel = new JLabel(skill.getName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setIcon(new ImageIcon(skillIconManager.getSkillImage(skill, true)));
		nameLabel.setIconTextGap(6);
		nameLabel.setInheritsPopupMenu(true);

		// XP/hr sits directly under the name, aligned with the skill icon.
		final JLabel rate = new JLabel(rateText(plugin.getXpPerHour(skill)));
		rate.setForeground(RATE_COLOR);
		rate.setInheritsPopupMenu(true);
		rateLabels.put(skill, rate);

		// Name over XP/hr; the checkbox stays in the row's WEST slot so
		// BorderLayout keeps it centered against the two lines.
		final JPanel namePanel = new JPanel();
		namePanel.setLayout(new BoxLayout(namePanel, BoxLayout.Y_AXIS));
		namePanel.setOpaque(false);
		namePanel.setInheritsPopupMenu(true);
		nameLabel.setAlignmentX(LEFT_ALIGNMENT);
		rate.setAlignmentX(LEFT_ALIGNMENT);
		namePanel.add(nameLabel);
		namePanel.add(rate);

		((BorderLayout) row.getLayout()).setHgap(6);
		row.add(overlayToggle, BorderLayout.WEST);
		row.add(namePanel, BorderLayout.CENTER);

		// Total (+session) top-aligned on the right, level with the name
		final JLabel value = new JLabel(gainedText(total, plugin.getSessionXp().get(skill)), SwingConstants.RIGHT);
		value.setForeground(Color.WHITE);
		value.setVerticalAlignment(SwingConstants.TOP);
		value.setInheritsPopupMenu(true);
		valueLabels.put(skill, value);
		row.add(value, BorderLayout.EAST);

		// Drag anywhere on the row except the checkbox, which keeps its click
		final DragHandler drag = new DragHandler(skill, row);
		for (Component c : new Component[]{row, namePanel, nameLabel, rate, value})
		{
			c.addMouseListener(drag);
			c.addMouseMotionListener(drag);
		}

		final JMenuItem resetSession = new JMenuItem("Reset " + skill.getName() + " session");
		resetSession.addActionListener(e -> plugin.resetSkillSession(skill));

		final JMenuItem resetRate = new JMenuItem("Reset " + skill.getName() + " XP/hr");
		resetRate.addActionListener(e -> plugin.resetSkillXpPerHour(skill));

		final JPopupMenu menu = new JPopupMenu();
		menu.add(resetSession);
		menu.add(resetRate);
		row.setComponentPopupMenu(menu);

		return row;
	}

	private JPanel buildSummaryRow(String name, JLabel value, String tooltip)
	{
		final JPanel row = baseRow();
		row.setToolTipText(tooltip);

		final JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(Color.WHITE);
		row.add(nameLabel, BorderLayout.WEST);
		row.add(value, BorderLayout.EAST);
		return row;
	}

	private static JPanel baseRow()
	{
		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(ROW_BORDER);
		return row;
	}

	/** Right-column text: total, with the session gain under it when enabled. */
	private String gainedText(long total, Long session)
	{
		final StringBuilder text = new StringBuilder("<html><div align='right'>")
			.append(QuantityFormatter.formatNumber(total));
		if (config.showSessionXp() && session != null && session > 0)
		{
			text.append("<br><font color='#a0a0a0'>+")
				.append(QuantityFormatter.formatNumber(session))
				.append("</font>");
		}
		text.append("</div></html>");
		return text.toString();
	}

	/** Left-column XP/hr line shown under the skill name; empty when disabled. */
	private String rateText(long xpPerHour)
	{
		if (!config.showXpPerHour() || xpPerHour < 0)
		{
			return "";
		}
		return QuantityFormatter.formatNumber(xpPerHour) + " xp/hr";
	}

	/**
	 * Index of the skill row under a y coordinate in {@link #skillList} space.
	 */
	private int rowIndexAt(int y)
	{
		for (int i = 0; i < skillRows.size(); i++)
		{
			final JPanel row = skillRows.get(i);
			if (y < row.getY() + row.getHeight())
			{
				return i;
			}
		}
		return skillRows.size() - 1;
	}

	private void setDropTarget(int index)
	{
		final JPanel target = index >= 0 && index < skillRows.size() ? skillRows.get(index) : null;
		if (target == dropTarget)
		{
			return;
		}
		if (dropTarget != null)
		{
			dropTarget.setBorder(ROW_BORDER);
		}
		dropTarget = target;
		if (dropTarget != null)
		{
			dropTarget.setBorder(DROP_BORDER);
		}
	}

	/**
	 * Reorders rows by dragging. The list is rebuilt on drop rather than
	 * during the drag, so the component receiving mouse events stays alive.
	 */
	private class DragHandler extends MouseAdapter
	{
		private final Skill skill;
		private final JPanel row;
		private boolean started;

		DragHandler(Skill skill, JPanel row)
		{
			this.skill = skill;
			this.row = row;
		}

		@Override
		public void mouseDragged(MouseEvent e)
		{
			if (!SwingUtilities.isLeftMouseButton(e))
			{
				return;
			}
			if (!started)
			{
				started = true;
				dragging = true;
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}
			setDropTarget(rowIndexAt(toListPoint(e).y));
		}

		@Override
		public void mouseReleased(MouseEvent e)
		{
			if (!started)
			{
				return;
			}
			started = false;
			dragging = false;

			final int target = rowIndexAt(toListPoint(e).y);
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setDropTarget(-1);
			// No-ops when the row didn't move; otherwise triggers a refresh
			plugin.moveSkillTo(skill, target);
		}

		private Point toListPoint(MouseEvent e)
		{
			return SwingUtilities.convertPoint((Component) e.getSource(), e.getPoint(), skillList);
		}
	}
}

