import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.QuantityFormatter;

@Slf4j
@PluginDescriptor(
	name = "Post 200M XP Tracker",
	description = "Tracks XP gained in skills that are already at 200M XP",
	tags = {"xp", "200m", "experience", "tracker", "max"}
)
public class Post200mPlugin extends Plugin
{
	private static final String KEY_PREFIX = "xp_";
	private static final String KEY_SKILL_ORDER = "skillOrder";
	private static final String KEY_OVERLAY_HIDDEN = "overlayHidden";

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private Post200mOverlay overlay;

	@Inject
	private Post200mConfig config;

	// All-time XP gained past 200M, persisted per RS profile (character).
	// Deliberately has no reset path.
	@Getter
	private final Map<Skill, Long> totalXp = new EnumMap<>(Skill.class);

	// Resettable XP counter shown on the overlay ("current session")
	@Getter
	private final Map<Skill, Long> sessionXp = new EnumMap<>(Skill.class);

	// Active-time tracking per skill for XP/hr, mirroring the built-in XP
	// Tracker: time between drops counts as active only up to the pause cutoff
	private final Map<Skill, RateTimer> rateTimers = new EnumMap<>(Skill.class);

	// XP/hr recomputed once per game tick so the display doesn't flicker
	private final Map<Skill, Long> cachedRates = new EnumMap<>(Skill.class);

	// Account XP as the game reports it (each skill capped at 200M), sampled
	// on the client thread so the panel can read it from the EDT
	private long overallXp;

	// Display order of skills in the panel and overlay; persisted
	private final List<Skill> skillOrder = new ArrayList<>();

	// Skills the user has hidden from the overlay; persisted. Storing the
	// hidden set (not the visible set) makes new skills visible by default.
	private final Set<Skill> overlayHidden = EnumSet.noneOf(Skill.class);

	private static class RateTimer
	{
		long lastDrop;
		long activeMillis;
		// XP counted towards the rate; separate from sessionXp so XP/hr can
		// be reset without touching the session or total figures
		long xp;

		RateTimer(long now)
		{
			lastDrop = now;
		}
	}

	private Post200mPanel panel;
	private NavigationButton navButton;
	private boolean navAdded;
	private String loadedProfile;

	@Override
	protected void startUp()
	{
		loadDisplayPrefs();

		panel = new Post200mPanel(this, config, skillIconManager);
		navButton = NavigationButton.builder()
			.tooltip("Post 200M XP Tracker")
			.icon(createIcon())
			.priority(6)
			.panel(panel)
			.build();

		overlayManager.add(overlay);
		updateNavButton();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadTotals();
		}
		refreshPanel();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		if (navAdded)
		{
			clientToolbar.removeNavigation(navButton);
			navAdded = false;
		}
		panel = null;
		navButton = null;
		totalXp.clear();
		sessionXp.clear();
		rateTimers.clear();
		cachedRates.clear();
		skillOrder.clear();
		overlayHidden.clear();
		overallXp = 0;
		loadedProfile = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadTotals();
			refreshPanel();
		}
	}

	@Subscribe
	public void onFakeXpDrop(FakeXpDrop event)
	{
		// Fires only for skills already at 200M; the server still reports the
		// xp the action would have given, and this event carries that amount.
		final int xp = event.getXp();
		if (xp <= 0 || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final Skill skill = event.getSkill();
		final long now = System.currentTimeMillis();
		final RateTimer timer = rateTimers.computeIfAbsent(skill, k -> new RateTimer(now));
		timer.activeMillis += Math.min(now - timer.lastDrop, pauseMillis());
		timer.lastDrop = now;
		timer.xp += xp;

		sessionXp.merge(skill, (long) xp, Long::sum);
		final long total = totalXp.merge(skill, (long) xp, Long::sum);
		configManager.setRSProfileConfiguration(Post200mConfig.GROUP, KEY_PREFIX + skill.name(), Long.toString(total));
		updatePanel();
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		overallXp = client.getOverallExperience();

		cachedRates.clear();
		final long now = System.currentTimeMillis();
		final long pause = pauseMillis();
		for (Map.Entry<Skill, RateTimer> entry : rateTimers.entrySet())
		{
			final RateTimer timer = entry.getValue();
			final long active = timer.activeMillis + Math.min(now - timer.lastDrop, pause);
			if (active > 0)
			{
				cachedRates.put(entry.getKey(), timer.xp * 3_600_000L / active);
			}
		}

		updatePanel();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (Post200mConfig.GROUP.equals(event.getGroup()) && "showSidePanel".equals(event.getKey()))
		{
			updateNavButton();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		switch (event.getCommand().toLowerCase())
		{
			case "200m":
				printTotals();
				break;
			case "200mreset":
				// Deliberately command-only: all-time totals have no reset
				// path in the UI, so this can't be hit by a stray click.
				resetTotals();
				break;
		}
	}

	private void resetTotals()
	{
		for (Skill skill : Skill.values())
		{
			configManager.unsetRSProfileConfiguration(Post200mConfig.GROUP, KEY_PREFIX + skill.name());
		}
		totalXp.clear();
		sessionXp.clear();
		rateTimers.clear();
		cachedRates.clear();
		refreshPanel();
		message("All-time post-200M XP totals reset for this character.");
	}

	/**
	 * XP per hour for a skill, updated once per game tick, or -1 if no
	 * rate is available yet.
	 */
	long getXpPerHour(Skill skill)
	{
		return cachedRates.getOrDefault(skill, -1L);
	}

	/**
	 * True account XP: what the game reports (capped at 200M per skill) plus
	 * everything tracked past the cap. 0 when not logged in yet.
	 */
	long getTotalAccountXp()
	{
		if (overallXp <= 0)
		{
			return 0;
		}
		return overallXp + totalXp.values().stream().mapToLong(Long::longValue).sum();
	}

	void resetSession()
	{
		sessionXp.clear();
		rateTimers.clear();
		cachedRates.clear();
		refreshPanel();
	}

	void resetSkillSession(Skill skill)
	{
		sessionXp.remove(skill);
		rateTimers.remove(skill);
		cachedRates.remove(skill);
		refreshPanel();
	}

	void resetXpPerHour()
	{
		rateTimers.clear();
		cachedRates.clear();
		refreshPanel();
	}

	void resetSkillXpPerHour(Skill skill)
	{
		rateTimers.remove(skill);
		cachedRates.remove(skill);
		refreshPanel();
	}

	boolean isSkillOnOverlay(Skill skill)
	{
		return !overlayHidden.contains(skill);
	}

	void setSkillOnOverlay(Skill skill, boolean show)
	{
		if (show)
		{
			overlayHidden.remove(skill);
		}
		else
		{
			overlayHidden.add(skill);
		}
		saveOverlayHidden();
	}

	/** Removes every tracked skill from the overlay (unticks all toggles). */
	void hideAllFromOverlay()
	{
		overlayHidden.addAll(totalXp.keySet());
		saveOverlayHidden();
		refreshPanel();
	}

	private void saveOverlayHidden()
	{
		configManager.setConfiguration(Post200mConfig.GROUP, KEY_OVERLAY_HIDDEN,
			overlayHidden.stream().map(Enum::name).collect(Collectors.joining(",")));
	}

	/**
	 * Skills with tracked XP, in the user's chosen display order. Skills
	 * without a saved position go at the end in enum order.
	 */
	List<Skill> getDisplaySkills()
	{
		final List<Skill> result = new ArrayList<>();
		for (Skill skill : skillOrder)
		{
			if (totalXp.containsKey(skill))
			{
				result.add(skill);
			}
		}
		for (Skill skill : totalXp.keySet())
		{
			if (!result.contains(skill))
			{
				result.add(skill);
			}
		}
		return result;
	}

	void moveSkillTo(Skill skill, int index)
	{
		final List<Skill> display = getDisplaySkills();
		final int from = display.indexOf(skill);
		if (from < 0 || index < 0 || index >= display.size() || from == index)
		{
			return;
		}

		display.remove(from);
		display.add(index, skill);
		skillOrder.clear();
		skillOrder.addAll(display);
		configManager.setConfiguration(Post200mConfig.GROUP, KEY_SKILL_ORDER,
			skillOrder.stream().map(Enum::name).collect(Collectors.joining(",")));
		refreshPanel();
	}

	private void updateNavButton()
	{
		if (config.showSidePanel() && !navAdded)
		{
			clientToolbar.addNavigation(navButton);
			navAdded = true;
		}
		else if (!config.showSidePanel() && navAdded)
		{
			clientToolbar.removeNavigation(navButton);
			navAdded = false;
		}
	}

	private void refreshPanel()
	{
		final Post200mPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refresh);
		}
	}

	/**
	 * Cheap per-tick update; the panel promotes it to a full rebuild if the
	 * rows themselves changed.
	 */
	private void updatePanel()
	{
		final Post200mPanel p = panel;
		if (p != null)
		{
			p.update();
		}
	}

	private void loadDisplayPrefs()
	{
		skillOrder.clear();
		overlayHidden.clear();
		for (Skill skill : parseSkills(configManager.getConfiguration(Post200mConfig.GROUP, KEY_SKILL_ORDER)))
		{
			if (!skillOrder.contains(skill))
			{
				skillOrder.add(skill);
			}
		}
		overlayHidden.addAll(parseSkills(configManager.getConfiguration(Post200mConfig.GROUP, KEY_OVERLAY_HIDDEN)));
	}

	private static List<Skill> parseSkills(String csv)
	{
		final List<Skill> result = new ArrayList<>();
		if (csv == null || csv.isEmpty())
		{
			return result;
		}
		for (String name : csv.split(","))
		{
			try
			{
				result.add(Skill.valueOf(name));
			}
			catch (IllegalArgumentException ex)
			{
				log.debug("Unknown skill in saved prefs: {}", name);
			}
		}
		return result;
	}

	private void loadTotals()
	{
		final String profile = configManager.getRSProfileKey();
		if (Objects.equals(profile, loadedProfile))
		{
			return;
		}

		totalXp.clear();
		sessionXp.clear();
		rateTimers.clear();
		cachedRates.clear();
		for (Skill skill : Skill.values())
		{
			final String saved = configManager.getRSProfileConfiguration(Post200mConfig.GROUP, KEY_PREFIX + skill.name());
			if (saved != null)
			{
				try
				{
					final long value = Long.parseLong(saved);
					if (value > 0)
					{
						totalXp.put(skill, value);
					}
				}
				catch (NumberFormatException ex)
				{
					log.debug("Invalid saved xp for {}: {}", skill, saved);
				}
			}
		}
		loadedProfile = profile;
	}

	private void printTotals()
	{
		if (totalXp.isEmpty())
		{
			message("No post-200M XP tracked yet.");
			return;
		}

		long grand = 0;
		for (Skill skill : getDisplaySkills())
		{
			final long total = totalXp.get(skill);
			grand += total;
			message(skill.getName() + ": " + QuantityFormatter.formatNumber(total) + " xp past 200M");
		}
		if (totalXp.size() > 1)
		{
			message("Total: " + QuantityFormatter.formatNumber(grand) + " xp past 200M");
		}
	}

	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", text, null);
	}

	private static BufferedImage createIcon()
	{
		final BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(255, 152, 31));
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		final FontMetrics fm = g.getFontMetrics();
		g.drawString("200", (24 - fm.stringWidth("200")) / 2, 10);
		g.drawString("M+", (24 - fm.stringWidth("M+")) / 2, 21);
		g.dispose();
		return img;
	}

	private long pauseMillis()
	{
		return config.pauseRateAfter() * 60_000L;
	}

	@Provides
	Post200mConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(Post200mConfig.class);
	}
}

package com.post200m;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * A thin horizontal line used to separate skill rows in the overlay. RuneLite's
 * component set has no divider, so this is the minimal LayoutableRenderableEntity
 * that PanelComponent can lay out like any other child.
 */
class SeparatorComponent implements LayoutableRenderableEntity
{
	private final int width;
	private final Color color;
	private Point preferredLocation = new Point();
	private final Rectangle bounds = new Rectangle();

	SeparatorComponent(int width, Color color)
	{
		this.width = width;
		this.color = color;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		graphics.setColor(color);
		graphics.drawLine(preferredLocation.x, preferredLocation.y, preferredLocation.x + width, preferredLocation.y);

		final Dimension dimension = new Dimension(width, 1);
		bounds.setLocation(preferredLocation);
		bounds.setSize(dimension);
		return dimension;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		this.preferredLocation = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		// Fixed width; nothing to do.
	}
}

